-- =====================================================================
-- Update database `aira` (Laravel 12, localhost) dari aira(3).sql (PDO)
-- Dibuat 17 Okt 2026. Jalankan di phpMyAdmin: pilih database `aira` -> Impor.
-- WAJIB: export/backup database `aira` dulu sebelum menjalankan file ini.
--
-- Isi:
--  1. barang id_barang <= 6072 : update stok_barang, hna, hrgsat_barang,
--                                hrgsat_grosir, hrgjual_barang dari aira3
--  2. barang id_barang >= 6073 : dihapus lalu diganti seluruhnya dari aira3
--                                (category_id diisi 0 = belum berkategori)
--  3. trbmasuk, trbmasuk_detail, trbmasuk_detail_hist,
--     trkasir, trkasir_detail, trkasir_detail_hist, trkasir_detail_ubah_qty
--     : isi lama dikosongkan, diganti seluruhnya dari aira3
--  Data aira3 dimuat dulu ke tabel sementara `_a3_*`, lalu dihapus di akhir.
-- =====================================================================
SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `_a3_barang`;
DROP TABLE IF EXISTS `_a3_trbmasuk`;
DROP TABLE IF EXISTS `_a3_trbmasuk_detail`;
DROP TABLE IF EXISTS `_a3_trbmasuk_detail_hist`;
DROP TABLE IF EXISTS `_a3_trkasir`;
DROP TABLE IF EXISTS `_a3_trkasir_detail`;
DROP TABLE IF EXISTS `_a3_trkasir_detail_hist`;
DROP TABLE IF EXISTS `_a3_trkasir_detail_ubah_qty`;
/*M!999999\- enable the sandbox mode */ 
CREATE TABLE `_a3_barang` (
  `id_barang` int(11) NOT NULL AUTO_INCREMENT,
  `kd_barang` bigint(20) NOT NULL,
  `nm_barang` varchar(100) NOT NULL,
  `stok_barang` double NOT NULL,
  `stok_buffer` double NOT NULL,
  `stok_grosir` int(11) NOT NULL,
  `sat_barang` varchar(15) NOT NULL,
  `sat_grosir` varchar(15) NOT NULL,
  `konversi` int(11) NOT NULL,
  `jenisobat` varchar(50) NOT NULL,
  `hna` double NOT NULL,
  `diskon` double NOT NULL,
  `hrgsat_barang` double NOT NULL,
  `hrgsat_grosir` int(11) NOT NULL,
  `hrgjual_barang` double NOT NULL,
  `hrgjual_barang1` double NOT NULL,
  `hrgjual_barang2` double NOT NULL,
  `hrgjual_barang3` double NOT NULL,
  `hrgjual_barang4` double NOT NULL,
  `hrgjual_barang5` double NOT NULL,
  `komisi` double NOT NULL,
  `zataktif` varchar(100) NOT NULL,
  `indikasi` text NOT NULL,
  `ket_barang` text NOT NULL,
  `dosis` varchar(100) NOT NULL,
  `waktu` datetime NOT NULL,
  `t30` int(11) NOT NULL,
  `t60` int(11) NOT NULL,
  `q30` int(11) NOT NULL,
  `gr` float NOT NULL,
  `petugas` varchar(100) NOT NULL,
  `status` enum('active','inactive') NOT NULL,
  `image` varchar(100) NOT NULL,
  `promosi` enum('standar','terlaris','diskon') NOT NULL,
  `tgl` date DEFAULT NULL,
  `updated_by` varchar(30) NOT NULL,
  PRIMARY KEY (`id_barang`),
  UNIQUE KEY `kd_barang` (`kd_barang`)
) ENGINE=InnoDB AUTO_INCREMENT=6983 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trbmasuk` (
  `id_trbmasuk` int(11) NOT NULL AUTO_INCREMENT,
  `id_resto` varchar(11) NOT NULL,
  `petugas` varchar(30) NOT NULL,
  `kd_trbmasuk` varchar(100) NOT NULL,
  `kd_orders` varchar(100) NOT NULL,
  `tgl_trbmasuk` date NOT NULL,
  `id_supplier` int(11) NOT NULL,
  `nm_supplier` varchar(50) NOT NULL,
  `tlp_supplier` varchar(50) NOT NULL,
  `alamat_trbmasuk` text NOT NULL,
  `ttl_trbmasuk` double NOT NULL,
  `dp_bayar` double NOT NULL,
  `sisa_bayar` double NOT NULL,
  `ket_trbmasuk` text NOT NULL,
  `jatuhtempo` varchar(20) NOT NULL,
  `carabayar` varchar(20) NOT NULL DEFAULT 'LUNAS',
  `jenis` enum('nonpbf','pbf') NOT NULL,
  `tgl_lunas` date NOT NULL,
  `petugas_lunas` varchar(100) NOT NULL,
  PRIMARY KEY (`id_trbmasuk`),
  UNIQUE KEY `kd_trbmasuk` (`kd_trbmasuk`),
  KEY `idx_trbmasuk_idresto_id` (`id_resto`,`id_trbmasuk`),
  KEY `idx_trbmasuk_idresto_kd` (`id_resto`,`kd_trbmasuk`),
  KEY `idx_trbmasuk_idresto_tgl` (`id_resto`,`tgl_trbmasuk`),
  KEY `idx_trbmasuk_idresto_supplier` (`id_resto`,`nm_supplier`),
  KEY `idx_trbmasuk_idresto_carabayar` (`id_resto`,`carabayar`)
) ENGINE=InnoDB AUTO_INCREMENT=444 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trbmasuk_detail` (
  `id_dtrbmasuk` int(11) NOT NULL AUTO_INCREMENT,
  `kd_trbmasuk` varchar(100) NOT NULL,
  `kd_orders` varchar(100) NOT NULL,
  `id_barang` int(11) NOT NULL,
  `kd_barang` varchar(50) NOT NULL,
  `nmbrg_dtrbmasuk` varchar(100) NOT NULL,
  `qty_dtrbmasuk` double NOT NULL,
  `sat_dtrbmasuk` varchar(30) NOT NULL,
  `qty_grosir` int(11) NOT NULL,
  `satgrosir_dtrbmasuk` varchar(30) NOT NULL,
  `hnasat_dtrbmasuk` double NOT NULL,
  `diskon` double NOT NULL,
  `konversi` int(11) NOT NULL,
  `hrgsat_dtrbmasuk` double NOT NULL,
  `hrgjual_dtrbmasuk` double NOT NULL,
  `hrgttl_dtrbmasuk` double NOT NULL,
  `no_batch` varchar(100) NOT NULL,
  `exp_date` date NOT NULL DEFAULT '2028-01-01',
  `waktu` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `tipe` int(11) NOT NULL,
  `tipe_barang` enum('reguler','bonus') NOT NULL DEFAULT 'reguler',
  PRIMARY KEY (`id_dtrbmasuk`),
  KEY `fk_barangmasuk` (`id_barang`),
  KEY `idx_trbmasuk_detail_kd_barang` (`kd_barang`)
) ENGINE=InnoDB AUTO_INCREMENT=2626 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trbmasuk_detail_hist` (
  `id_dtrbmasuk` int(11) NOT NULL AUTO_INCREMENT,
  `kd_trbmasuk` varchar(100) NOT NULL,
  `kd_orders` varchar(100) NOT NULL,
  `id_barang` int(11) NOT NULL,
  `kd_barang` varchar(50) NOT NULL,
  `nmbrg_dtrbmasuk` varchar(100) NOT NULL,
  `qty_dtrbmasuk` double NOT NULL,
  `sat_dtrbmasuk` varchar(30) NOT NULL,
  `qty_grosir` int(11) NOT NULL,
  `satgrosir_dtrbmasuk` varchar(30) NOT NULL,
  `hnasat_dtrbmasuk` double NOT NULL,
  `diskon` double NOT NULL,
  `konversi` int(11) NOT NULL,
  `hrgsat_dtrbmasuk` double NOT NULL,
  `hrgjual_dtrbmasuk` double NOT NULL,
  `hrgttl_dtrbmasuk` double NOT NULL,
  `no_batch` varchar(100) NOT NULL,
  `exp_date` date NOT NULL DEFAULT '2028-01-01',
  `waktu` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `tipe` int(11) NOT NULL,
  PRIMARY KEY (`id_dtrbmasuk`)
) ENGINE=InnoDB AUTO_INCREMENT=262 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trkasir` (
  `id_trkasir` int(11) NOT NULL AUTO_INCREMENT,
  `kd_trkasir` varchar(100) NOT NULL,
  `id_user` int(11) NOT NULL,
  `petugas` varchar(100) NOT NULL,
  `shift` int(11) NOT NULL,
  `tgl_trkasir` date NOT NULL,
  `id_pelanggan` int(11) NOT NULL,
  `nm_pelanggan` varchar(100) NOT NULL,
  `tlp_pelanggan` varchar(50) NOT NULL,
  `alamat_pelanggan` text NOT NULL,
  `kodetx` varchar(20) DEFAULT NULL,
  `ttl_trkasir` double NOT NULL,
  `dp_bayar` double DEFAULT NULL,
  `diskon1` double DEFAULT NULL,
  `diskon2` double DEFAULT NULL,
  `sisa_bayar` double DEFAULT NULL,
  `ket_trkasir` text DEFAULT NULL,
  `id_carabayar` int(11) NOT NULL DEFAULT 1,
  `jenistx` int(11) NOT NULL,
  `tipetx` int(11) NOT NULL DEFAULT 1,
  `waktu_trx` datetime DEFAULT NULL,
  `poin_awal` int(11) NOT NULL,
  `tambahan_poin` int(11) NOT NULL,
  `redeem_poin` int(11) NOT NULL,
  PRIMARY KEY (`id_trkasir`),
  UNIQUE KEY `kd_trkasir` (`kd_trkasir`),
  KEY `idx_trkasir_shift_tgl_carabayar_kd` (`shift`,`tgl_trkasir`,`id_carabayar`,`kd_trkasir`)
) ENGINE=InnoDB AUTO_INCREMENT=5300 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trkasir_detail` (
  `id_dtrkasir` int(11) NOT NULL AUTO_INCREMENT,
  `kd_trkasir` varchar(100) NOT NULL,
  `id_barang` int(11) NOT NULL,
  `kd_barang` varchar(50) NOT NULL,
  `nmbrg_dtrkasir` varchar(100) NOT NULL,
  `qty_dtrkasir` double NOT NULL,
  `sat_dtrkasir` varchar(30) NOT NULL,
  `hrgjual_dtrkasir` double NOT NULL,
  `disc` int(2) DEFAULT NULL,
  `modal` double NOT NULL,
  `profit` double NOT NULL,
  `hrgttl_dtrkasir` double NOT NULL,
  `no_batch` varchar(20) DEFAULT NULL,
  `exp_date` date DEFAULT NULL,
  `waktu` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `tipe` int(11) NOT NULL,
  `komisi` int(11) DEFAULT NULL,
  `idadmin` int(11) NOT NULL,
  `tipetx` int(11) NOT NULL DEFAULT 1,
  `resep` enum('YA','TIDAK') NOT NULL DEFAULT 'TIDAK',
  PRIMARY KEY (`id_dtrkasir`),
  KEY `idx_trkasir_detail_kd_barang` (`kd_barang`),
  KEY `idx_trkasir_detail_kdtrkasir_nmbrg` (`kd_trkasir`,`nmbrg_dtrkasir`),
  KEY `idx_trkasir_detail_id_barang` (`id_barang`)
) ENGINE=InnoDB AUTO_INCREMENT=9446 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trkasir_detail_hist` (
  `id_dtrkasir` int(11) NOT NULL AUTO_INCREMENT,
  `kd_trkasir` varchar(100) NOT NULL,
  `id_barang` int(11) NOT NULL,
  `kd_barang` varchar(50) NOT NULL,
  `nmbrg_dtrkasir` varchar(100) NOT NULL,
  `qty_dtrkasir` double NOT NULL,
  `sat_dtrkasir` varchar(30) NOT NULL,
  `hrgjual_dtrkasir` double NOT NULL,
  `disc` int(2) DEFAULT NULL,
  `resep` enum('TIDAK','YA') NOT NULL DEFAULT 'TIDAK',
  `hrgttl_dtrkasir` double NOT NULL,
  `no_batch` varchar(20) NOT NULL,
  `exp_date` date DEFAULT NULL,
  `waktu` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `tipe` int(11) NOT NULL,
  `komisi` int(11) DEFAULT NULL,
  `idadmin` int(11) NOT NULL,
  `tipetx_asal` int(11) NOT NULL DEFAULT 1,
  `tipetx_hapus` int(11) NOT NULL DEFAULT 1,
  `waktu_hapus` timestamp NOT NULL DEFAULT current_timestamp(),
  `id_admin_hapus` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_dtrkasir`)
) ENGINE=InnoDB AUTO_INCREMENT=747 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
CREATE TABLE `_a3_trkasir_detail_ubah_qty` (
  `id_log` bigint(20) NOT NULL AUTO_INCREMENT,
  `kd_trkasir` varchar(100) NOT NULL,
  `id_dtrkasir` int(11) NOT NULL,
  `kd_barang` varchar(50) NOT NULL,
  `nmbrg_dtrkasir` varchar(100) NOT NULL,
  `qty_sebelum` double NOT NULL,
  `qty_sesudah` double NOT NULL,
  `hrgttl_sebelum` double NOT NULL,
  `hrgttl_sesudah` double NOT NULL,
  `tipetx` int(11) NOT NULL,
  `id_admin` int(11) DEFAULT NULL,
  `waktu` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_log`),
  KEY `idx_trkasir_detail_ubah_qty_kd_trkasir` (`kd_trkasir`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

START TRANSACTION;

-- 1. Update 5 kolom harga & stok untuk barang id <= 6072
UPDATE `barang` b
JOIN `_a3_barang` a ON a.id_barang = b.id_barang
SET b.stok_barang   = a.stok_barang,
    b.hna           = a.hna,
    b.hrgsat_barang = a.hrgsat_barang,
    b.hrgsat_grosir = a.hrgsat_grosir,
    b.hrgjual_barang= a.hrgjual_barang
WHERE b.id_barang <= 6072;

-- 2. Ganti barang id >= 6073 dengan data aira3
DELETE FROM `barang` WHERE id_barang >= 6073;
  sat_barang, sat_grosir, konversi, jenisobat, hna, diskon, hrgsat_barang, hrgsat_grosir, hrgjual_barang,
  hrgjual_barang1, hrgjual_barang2, komisi, zataktif, indikasi, ket_barang, dosis, waktu, t30, t60, gr, q30,
  petugas, status, image, promosi, tgl, updated_by)
SELECT id_barang, kd_barang, 0, nm_barang, stok_barang, stok_buffer, stok_grosir,
  sat_barang, sat_grosir, konversi, jenisobat, hna, diskon, hrgsat_barang, hrgsat_grosir, hrgjual_barang,
  hrgjual_barang1, hrgjual_barang2, komisi, zataktif, indikasi, ket_barang, dosis, waktu, t30, t60, ROUND(gr), q30,
  petugas, status, image, promosi, tgl, updated_by
FROM `_a3_barang` WHERE id_barang >= 6073;

-- 3. Transaksi pembelian
DELETE FROM `trbmasuk_detail_hist`;
DELETE FROM `trbmasuk_detail`;
DELETE FROM `trbmasuk`;

-- 4. Transaksi penjualan
DELETE FROM `trkasir_detail_ubah_qty`;
DELETE FROM `trkasir_detail_hist`;
DELETE FROM `trkasir_detail`;
DELETE FROM `trkasir`;

  sat_dtrkasir, hrgjual_dtrkasir, disc, modal, profit, hrgttl_dtrkasir, no_batch, exp_date, waktu, tipe,
  komisi, idadmin, id_reseller, tipetx, resep, kd_bundle, nm_bundle)
SELECT id_dtrkasir, kd_trkasir, id_barang, kd_barang, nmbrg_dtrkasir, qty_dtrkasir,
  sat_dtrkasir, hrgjual_dtrkasir, disc, modal, profit, hrgttl_dtrkasir, no_batch, exp_date, waktu, tipe,
  komisi, idadmin, NULL, tipetx, resep, '', ''
FROM `_a3_trkasir_detail`;

  sat_dtrkasir, hrgjual_dtrkasir, disc, modal, profit, hrgttl_dtrkasir, no_batch, exp_date, waktu, tipe,
  komisi, idadmin, tipetx_asal, tipetx_hapus, waktu_hapus, id_admin_hapus, resep, kd_bundle, nm_bundle)
SELECT id_dtrkasir, kd_trkasir, id_barang, kd_barang, nmbrg_dtrkasir, qty_dtrkasir,
  sat_dtrkasir, hrgjual_dtrkasir, disc, 0, 0, hrgttl_dtrkasir, no_batch, exp_date, waktu, tipe,
  komisi, idadmin, tipetx_asal, tipetx_hapus, waktu_hapus, id_admin_hapus, resep, '', ''
FROM `_a3_trkasir_detail_hist`;


COMMIT;

-- Bersihkan tabel sementara
DROP TABLE IF EXISTS `_a3_barang`;
DROP TABLE IF EXISTS `_a3_trbmasuk`;
DROP TABLE IF EXISTS `_a3_trbmasuk_detail`;
DROP TABLE IF EXISTS `_a3_trbmasuk_detail_hist`;
DROP TABLE IF EXISTS `_a3_trkasir`;
DROP TABLE IF EXISTS `_a3_trkasir_detail`;
DROP TABLE IF EXISTS `_a3_trkasir_detail_hist`;
DROP TABLE IF EXISTS `_a3_trkasir_detail_ubah_qty`;
SET FOREIGN_KEY_CHECKS = 1;
